#include "geodesy.h"
#include "math3d.h"
#include <math.h>
#include <stdio.h>
#define CHECK(v,e,t) do{if(fabs((v)-(e))>(t)){printf("FAIL line %d: %.12g != %.12g\n",__LINE__,(double)(v),(double)(e));return 1;}}while(0)
int main(void){Vec3 p=geodetic_to_ecef((Geodetic){0,0,0});CHECK(p.x,WGS84_A,1e-8);CHECK(p.y,0,1e-8);CHECK(p.z,0,1e-8);p=geodetic_to_ecef((Geodetic){90,0,0});CHECK(p.x,0,1e-7);CHECK(p.y,0,1e-7);CHECK(p.z,WGS84_A*(1-WGS84_F),1e-6);Geodetic g;p=geodetic_to_ecef((Geodetic){37.25,-122.1,1234.5});if(!ecef_to_geodetic(p,&g))return 1;CHECK(g.latitude_deg,37.25,1e-9);CHECK(g.longitude_deg,-122.1,1e-9);CHECK(g.altitude_m,1234.5,1e-5);Mat3 r=ned_to_ecef_matrix(0,0);Vec3 n=apply(r,(Vec3){1,0,0});CHECK(n.x,0,1e-12);CHECK(n.y,0,1e-12);CHECK(n.z,1,1e-12);Vec3 e=apply(r,(Vec3){0,1,0});CHECK(e.x,0,1e-12);CHECK(e.y,1,1e-12);CHECK(e.z,0,1e-12);Vec3 d=apply(r,(Vec3){0,0,1});CHECK(d.x,-1,1e-12);CHECK(d.y,0,1e-12);CHECK(d.z,0,1e-12);Mat3 q=node_rot((Attitude){0,30,0});Vec3 f=apply(q,(Vec3){1,0,0});CHECK(f.x,cos(30*GEO_DEG_TO_RAD),1e-12);CHECK(f.z,-sin(30*GEO_DEG_TO_RAD),1e-12);Mat3 qt=mat3_transpose(q),identity=mat3_multiply(q,qt);for(int i=0;i<3;i++)for(int j=0;j<3;j++)CHECK(identity.m[i][j],i==j?1.0:0.0,1e-12);puts("geodesy and attitude tests passed");return 0;}
